module clkgenerator (
	input reset, enable, period, 
	output clk
);
	integer counter;
	reg clkReg;
	initial begin
		counter = 0;
		clkReg = 0;
	end

	always@(posedge reset) begin
		if(reset == 0 && counter >= (period >> 1)) begin
			clkReg <= ~clkReg;
			counter <= 0;
		end

		else if(counter < (period >> 1))
			counter <= counter + 1;

	end

	assign clk = clkReg;
endmodule
